---
graph TD;
	__start__([<p>__start__</p>]):::first
	classify(classify)
	retrieve(retrieve)
	assess(assess)
	rewrite(rewrite)
	known_issues(known_issues)
	respond(respond)
	tools(tools)
	finish(finish)
	escalate(escalate)
	validate(validate)
	repair(repair)
	__end__([<p>__end__</p>]):::last
	__start__ --> classify;
	assess -.-> escalate;
	assess -.-> known_issues;
	assess -.-> respond;
	assess -.-> rewrite;
	classify --> retrieve;
	escalate --> validate;
	finish --> validate;
	known_issues --> respond;
	respond -.-> finish;
	respond -.-> tools;
	retrieve --> assess;
	rewrite --> retrieve;
	tools -.-> finish;
	tools -.-> respond;
	validate -.-> __end__;
	validate -.-> repair;
	repair --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
